diff --git a/solution.mjs b/solution.mjs
new file mode 100644
index 0000000..ab82fbc
--- /dev/null
+++ b/solution.mjs
@@ -0,0 +1,12 @@
+export function chunk(arr, size) {
+  const result = [];
+  let current = [];
+  for (const item of arr) {
+    current.push(item);
+    if (current.length === size) {
+      result.push(current);
+      current = [];
+    }
+  }
+  return result;
+}
